{{ config(
            materialized='table',
                post_hook={
                    "sql": "ALTER SESSION SET TIMEZONE = \'Asia/Kolkata\'; CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.FORWARD_PERFECT_ORDER AS with uc as ( select distinct awb, order_name , warehouse_name, uc_created,tat, packed_time, error, dispatched_timestamp, sla_status, tat_type from snitch_db.maplemonk.warehouse_sla_performance where marketplace_mapped = \'SHOPIFY\' and uc_created::DATE >= \'2025-06-01\' and warehouse_name like \'%SAPL%\' and sla_status not in (\'CANCELLED\') ), cp as ( select awb_number, assigned_date, pickup_date, delivery_date, status, order_id, outfordelivery_date, out_for_delivery_attempts, courier_partner, max_sla, min_sla, edd_cp, payment_method, pincode, mapped_city, final_state, final_zone from snitch_db.maplemonk.cp_1 where mode = \'Forward\' ), compile as ( select EXTRACT(MONTH,UC_CREATED) AS MONTH, uc_created::DATE + (max_sla::DATE - pickup_date::DATE) as revised_sla, (max_sla::DATE - assigned_date::DATE) as edd, CASE WHEN (delivery_date) is null and revised_sla < current_date then \'IMPERFECT\' WHEN (delivery_date) is null and revised_sla >= current_date then \'FUTURE\' WHEN revised_sla::DATE >= delivery_date::DATE then \'PERFECT\' else \'IMPERFECT\' end as CUSTOMER_POV, CASE WHEN (outfordelivery_date) is null and revised_sla < current_date then \'IMPERFECT\' WHEN (outfordelivery_date) is null and revised_sla >= current_date then \'FUTURE\' WHEN revised_sla::DATE >= outfordelivery_date::DATE then \'PERFECT\' else \'IMPERFECT\' end as CUSTOMER_POV_ATTEMPT, CASE WHEN warehouse_name = \'SAPL_EMIZA\' and courier_partner = \'Blitz (Formerly Grow Simplee)\' then tat + INTERVAL \'18 hours\' WHEN warehouse_name = \'SAPL_EMIZA\' and courier_partner = \'Bluedart\' then tat + INTERVAL \'18 hours\' WHEN warehouse_name = \'SAPL_EMIZA\' and courier_partner = \'Proship B2C\' then tat + INTERVAL \'18 hours\' WHEN warehouse_name = \'SAPL_EMIZA\' and courier_partner = \'Delhivery\' then tat + INTERVAL \'18 hours\' WHEN warehouse_name = \'SAPL_EMIZA\' and courier_partner = \'Ekart Logistics\' then tat + INTERVAL \'18 hours\' WHEN warehouse_name = \'SAPL_EMIZA\' and courier_partner = \'Shadowfax\' then tat + INTERVAL \'6 hours\' WHEN warehouse_name like \'%SAPL-WH%\' and courier_partner = \'Blitz (Formerly Grow Simplee)\' then tat + INTERVAL \'9 hours\' WHEN warehouse_name like \'%SAPL-WH%\' and courier_partner = \'Bluedart\' then tat + INTERVAL \'8 hours\' WHEN warehouse_name like \'%SAPL-WH%\' and courier_partner = \'Proship B2C\' then tat + INTERVAL \'18 hours\' WHEN warehouse_name like \'%SAPL-WH%\' and courier_partner = \'Delhivery\' then tat + INTERVAL \'18 hours\' WHEN warehouse_name like \'%SAPL-WH%\' and courier_partner = \'Ekart Logistics\' then tat + INTERVAL \'18 hours\' WHEN warehouse_name like \'%SAPL-WH%\' and courier_partner = \'Shadowfax\' then tat + INTERVAL \'6 hours\' else null end as Handover_TAT, CASE WHEN pickup_date > handover_tat THEN \'IMPERFECT\' else \'PERFECT\' end as PICKUP_POV, CASE WHEN outfordelivery_date is null and min_sla >= current_date THEN \'FUTURE\' when outfordelivery_date is null or outfordelivery_date::DATE > min_sla::DATE THEN \'IMPERFECT\' else \'PERFECT\' end as MIN_ATTEMPT_POV, CASE WHEN outfordelivery_date is null and max_sla >= current_date THEN \'FUTURE\' when outfordelivery_date is null or outfordelivery_date::DATE > max_sla::DATE THEN \'IMPERFECT\' else \'PERFECT\' end as ATTEMPT_POV, CASE WHEN delivery_date is null and min_sla >= current_date THEN \'FUTURE\' when delivery_date is null or delivery_date::DATE > min_sla::DATE THEN \'IMPERFECT\' else \'PERFECT\' end as min_delivery_pov, CASE WHEN delivery_date is null and max_sla >= current_date THEN \'FUTURE\' when delivery_date is null or delivery_date::DATE > max_sla::DATE THEN \'IMPERFECT\' else \'PERFECT\' end as delivery_pov, CASE WHEN ATTEMPT_POV = \'IMPERFECT\' or delivery_pov = \'IMPERFECT\' or pickup_pov = \'IMPERFECT\' then \'Operational_Gap\' else \'No Gap\' end as ops_delivery, CASE WHEN MIN_ATTEMPT_POV = \'IMPERFECT\' or min_delivery_pov = \'IMPERFECT\' or pickup_pov = \'IMPERFECT\' then \'Operational_Gap\' else \'No Gap\' end as min_ops_delivery, CASE WHEN ATTEMPT_POV = \'IMPERFECT\' or pickup_pov = \'IMPERFECT\' then \'Operational_Gap\' else \'No Gap\' end as Ops_attempt, CASE WHEN MIN_ATTEMPT_POV = \'IMPERFECT\' or pickup_pov = \'IMPERFECT\' then \'Operational_Gap\' else \'No Gap\' end as MIN_Ops_attempt, * from uc left join cp on uc.awb = cp.awb_number ) select *from compile where Handover_TAT is not null ; SELECT DATE_TRUNC(\'WEEK\', revised_sla) AS week_start, COUNT(DISTINCT awb) AS Shipments, 100* div0(COUNT(DISTINCT CASE WHEN outfordelivery_date::DATE <= revised_sla THEN awb END), COUNT(DISTINCT awb))AS OTA, 100* div0(COUNT(DISTINCT CASE WHEN delivery_date::DATE <= revised_sla THEN awb END),COUNT(DISTINCT awb)) AS OTD, 100* div0(COUNT(DISTINCT CASE WHEN delivery_date::DATE <= revised_sla + INTERVAL \'1 DAY\' THEN awb END),COUNT(DISTINCT awb)) AS OTD1 FROM SNITCH_DB.MAPLEMONK.FORWARD_PERFECT_ORDER where revised_sla >= current_date - 21 and pickup_date is not null and lower(status) not like \'%rto%\' and lower(status) not like \'%canc%\' and lower(status) not like \'%lost%\' group by 1 order by 1 desc",
                    "transaction": true
                }
            ) }}
